type RegistrationsByDaySinceRow struct {
	Day   time.Time `json:"day"`
	Count int64     `json:"count"`
}

func (q *Queries) RegistrationsByDaySince(ctx context.Context, createdAt time.Time) ([]RegistrationsByDaySinceRow, error) {
	rows, err := q.db.Query(ctx, registrationsByDaySince, createdAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RegistrationsByDaySinceRow{}
	for rows.Next() {
		var i RegistrationsByDaySinceRow
		if err := rows.Scan(&i.Day, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateUser = `-- name: UpdateUser :execrows
UPDATE users
SET email           = $2,
    first_name      = $3,
    last_name       = $4,
    hashed_password = $5,
    picture         = $6,
    role            = $7,
    status          = $8,
    email_confirmed = $9,
    tos_accepted_at = $10,
    tos_version     = $11,
    updated_at      = $12,
    updated_by      = $13,
    deleted_at      = $14
WHERE id = $1
  -- Optimistic lock: the caller sends the updated_at it loaded; a concurrent
  -- write moved it, so 0 rows means "modified since read" (or gone).
  AND updated_at IS NOT DISTINCT FROM $15
`

type UpdateUserParams struct {
	ID                uuid.UUID          `json:"id"`
	Email             string             `json:"email"`
	FirstName         string             `json:"first_name"`
	LastName          string             `json:"last_name"`
	HashedPassword    pgtype.Text        `json:"hashed_password"`
	Picture           string             `json:"picture"`
	Role              string             `json:"role"`
	Status            string             `json:"status"`
	EmailConfirmed    bool               `json:"email_confirmed"`
	TosAcceptedAt     pgtype.Timestamptz `json:"tos_accepted_at"`
	TosVersion        pgtype.Int4        `json:"tos_version"`
	UpdatedAt         pgtype.Timestamptz `json:"updated_at"`
	UpdatedBy         uuid.NullUUID      `json:"updated_by"`
	DeletedAt         pgtype.Timestamptz `json:"deleted_at"`
	ExpectedUpdatedAt pgtype.Timestamptz `json:"expected_updated_at"`
}

// Whole-aggregate write for the User entity: the repository maps the full
// domain model here. Deliberately excludes last_seen (owned by the async
// touch hot path — including it would race and lose updates) and created_at
// (immutable). updated_at comes from the domain (touch), not now().
func (q *Queries) UpdateUser(ctx context.Context, arg UpdateUserParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateUser,
		arg.ID,
		arg.Email,
		arg.FirstName,
		arg.LastName,
		arg.HashedPassword,
		arg.Picture,
		arg.Role,
		arg.Status,
		arg.EmailConfirmed,
		arg.TosAcceptedAt,
		arg.TosVersion,
		arg.UpdatedAt,
		arg.UpdatedBy,
		arg.DeletedAt,
		arg.ExpectedUpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateUserLastSeen = `-- name: UpdateUserLastSeen :execrows
UPDATE users
SET last_seen = GREATEST(last_seen, $1)
WHERE id = $2
`

type UpdateUserLastSeenParams struct {
	SeenAt time.Time `json:"seen_at"`
	ID     uuid.UUID `json:"id"`
}

func (q *Queries) UpdateUserLastSeen(ctx context.Context, arg UpdateUserLastSeenParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateUserLastSeen, arg.SeenAt, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
